package com.abdickers.realms;

import android.app.*;
import android.os.Bundle;
import android.widget.*;
import org.json.*;
import java.util.*;
import java.util.concurrent.Executors;

/** Explicit thermostat actions, revalidated by the existing server command allowlist. */
public final class ThermostatActivity extends Activity {
 private LinearLayout root;private TextView status;private JSONObject device;private boolean busy,closed;private final List<Button> actions=new ArrayList<>();
 @Override protected void onCreate(Bundle state){super.onCreate(state);ScrollView scroll=new ScrollView(this);root=new LinearLayout(this);root.setOrientation(1);root.setPadding(24,90,24,24);root.setBackgroundColor(0xFF171D23);scroll.addView(root);setContentView(scroll);status=text("Loading your thermostat…");String id=getIntent().getStringExtra("device");if(id==null||!id.matches("[A-Za-z0-9_-]{1,256}")){finish();return;}var executor=Executors.newSingleThreadExecutor();executor.execute(()->{try{JSONArray devices=HomeConnection.call(this,"/devices",null).getJSONArray("devices");for(int n=0;n<Math.min(25,devices.length());n++)if(id.equals(devices.getJSONObject(n).optString("id"))&&devices.getJSONObject(n).optString("type").equals("THERMOSTAT"))device=devices.getJSONObject(n);if(device==null)throw new IllegalStateException("This thermostat is no longer available.");runOnUiThread(()->{if(!closed)render();});}catch(Exception e){runOnUiThread(()->status.setText("The thermostat could not be loaded. Reconnect Home or try again."));}finally{executor.shutdown();}});}
 private void render(){status.setText(device.optString("name","The hearth")+" · "+HomeFeed.temperature(device.opt("temperature"))+"\n"+device.optString("mode")+" · "+device.optString("online"));JSONArray available=device.optJSONArray("modes");List<String> modes=new ArrayList<>();if(available!=null)for(int n=0;n<available.length();n++)if(Set.of("HEAT","COOL","HEATCOOL","OFF").contains(available.optString(n)))modes.add(available.optString(n));
  text("Mode");Spinner mode=new Spinner(this);mode.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,modes));int selected=modes.indexOf(device.optString("mode"));if(selected>=0)mode.setSelection(selected);root.addView(mode);button("Apply mode",()->{if(mode.getSelectedItem()==null)return;try{send(new JSONObject().put("deviceId",device.getString("id")).put("action","mode").put("mode",mode.getSelectedItem().toString()));}catch(Exception e){status.setText("Choose a valid mode.");}});
  String current=device.optString("mode");JSONObject targets=device.optJSONObject("setpoint");Map<String,EditText> fields=new HashMap<>();for(String field:current.equals("HEAT")?List.of("heatCelsius"):current.equals("COOL")?List.of("coolCelsius"):current.equals("HEATCOOL")?List.of("heatCelsius","coolCelsius"):List.<String>of()){text(field.startsWith("heat")?"Heat target °F":"Cool target °F");EditText input=new EditText(this);input.setInputType(android.text.InputType.TYPE_CLASS_NUMBER|android.text.InputType.TYPE_NUMBER_FLAG_DECIMAL);if(targets!=null&&targets.opt(field) instanceof Number number)input.setText(String.valueOf(Math.round(number.doubleValue()*9/5+32)));root.addView(input);fields.put(field,input);}
  if(!fields.isEmpty())button("Apply temperature",()->{try{JSONObject command=new JSONObject().put("deviceId",device.getString("id")).put("action","setpoint");for(var field:fields.entrySet()){double fahrenheit=Double.parseDouble(field.getValue().getText().toString());if(!Double.isFinite(fahrenheit)||fahrenheit<50||fahrenheit>89.6)throw new IllegalArgumentException();command.put(field.getKey(),(fahrenheit-32)*5/9);}send(command);}catch(Exception e){status.setText("Enter a target between 50 and 89.6 °F. Keep Heat/Cool targets at least 3 °F apart.");}});
  if(!device.optString("online").equals("ONLINE")){for(Button action:actions)action.setEnabled(false);text("Thermostat is offline. Controls are unavailable.");}
  Button back=new Button(this);back.setText("Back to dashboard");back.setOnClickListener(v->finish());root.addView(back);
 }
 private void send(JSONObject command){if(busy)return;busy=true;for(Button action:actions)action.setEnabled(false);status.setText("Applying thermostat change…");var executor=Executors.newSingleThreadExecutor();executor.execute(()->{try{HomeConnection.call(this,"/thermostat",command);Refresh.enqueue(this,"home","hearth",WidgetState.day(this,0));runOnUiThread(()->{if(!closed){status.setText("Change applied.");recreate();}});}catch(Exception e){runOnUiThread(()->{if(!closed){status.setText("The change could not be applied. Refresh to check the thermostat before trying again.");busy=false;for(Button action:actions)action.setEnabled(true);}});}finally{executor.shutdown();}});}
 private TextView text(String value){TextView label=new TextView(this);label.setText(value);label.setTextColor(0xFFE8EDF4);label.setTextSize(18);label.setPadding(0,16,0,12);root.addView(label);return label;}
 private void button(String title,Runnable handler){Button button=new Button(this);button.setText(title);button.setAllCaps(false);button.setBackgroundResource(R.drawable.royal_button);button.setTextColor(0xFFE8EDF4);button.setOnClickListener(v->handler.run());actions.add(button);root.addView(button);}
 @Override protected void onDestroy(){closed=true;super.onDestroy();}
}
